from flask import Flask, request
import html
app = Flask(__name__)

LINGUISTS = {
    'noam_chomsky': 'Noam Chomsky',
    'edward_halevy': 'Edward Hallevy',
    'john_founded': 'John founded'
}

@app.route('/lang')
def lang():
    lang = request.args.get('lang')

    if lang not in LINGUISTS:
        return 'Invalid language'

    html_lang = html.escape(lang)
    return f'Welcome {LINGUISTS[html_lang]}. I hope you have a great meal and we can discuss all the things you love about {html_lang}!'
